#!/usr/bin/env node
// Replaces the placeholder value infrastructure/envs/<env>/main.tf's
// aws_ssm_parameter.auth_token_pepper is created with, exactly once, right
// after that resource's first apply for a given environment. Unlike the
// Paystack secret (a founder-owned external credential replaced manually in
// the AWS Console), this value has no external owner — it's an internal
// HMAC key generated by this script and written directly via the AWS CLI,
// using the same authenticated session that ran the apply. It is never
// printed, logged, or returned by this script.
//
// Idempotent by design: checks the parameter's Version via metadata only
// (never --with-decryption, matching how the Paystack replacement was
// verified in Phase 6) and only writes a new value when Version is still 1
// (i.e. still the Terraform-created placeholder). A second run is a safe
// no-op, not a silent rotation — rotating this value invalidates every
// outstanding session/magic-link token, which must always be a deliberate
// action, never an accidental side effect of re-running this script.
import { randomBytes } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

function parseArgs(argv) {
  const args = { env: null };
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === '--env') args.env = argv[++i];
  }
  return args;
}

function awsJson(cliArgs) {
  const out = execFileSync('aws', cliArgs, { encoding: 'utf8' });
  return JSON.parse(out);
}

async function main() {
  const { env } = parseArgs(process.argv.slice(2));
  if (!env || !['test', 'production'].includes(env)) {
    console.error('Usage: node scripts/generate-auth-token-pepper.mjs --env <test|production>');
    process.exit(1);
  }

  const paramName = `/zoryvex/${env}/auth/token-pepper`;

  const current = awsJson([
    'ssm',
    'get-parameter',
    '--name',
    paramName,
    '--query',
    'Parameter.{Version:Version,Type:Type}',
    '--output',
    'json',
  ]);

  if (current.Type !== 'SecureString') {
    console.error(`${paramName} is not a SecureString — refusing to touch it.`);
    process.exit(1);
  }

  if (current.Version > 1) {
    console.log(`${paramName} already has a real value (version ${current.Version}) — no-op.`);
    return;
  }

  const value = randomBytes(32).toString('base64url');
  const tmpDir = mkdtempSync(join(tmpdir(), 'zoryvex-pepper-'));
  const tmpFile = join(tmpDir, 'value');
  try {
    // Written to a temp file rather than passed as a --value CLI argument,
    // so the generated value never appears in a process listing.
    writeFileSync(tmpFile, value, { mode: 0o600 });
    execFileSync(
      'aws',
      [
        'ssm',
        'put-parameter',
        '--name',
        paramName,
        '--type',
        'SecureString',
        '--overwrite',
        '--value',
        `file://${tmpFile}`,
      ],
      { stdio: ['ignore', 'ignore', 'inherit'] },
    );
  } finally {
    rmSync(tmpDir, { recursive: true, force: true });
  }

  console.log(`${paramName} generated (version 1 -> 2). Value never printed.`);
}

main().catch((err) => {
  console.error(err.message ?? err);
  process.exit(1);
});
